    {
      "card_ids": ["C08"],
      "claim": "Propranolol absolute bioavailability in humans was 30–35% after oral tablets versus IV, directly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "KNI-272 absolute bioavailability was 36.40% in patients after an oral capsule in the post-prandial state, matching the fed-state query condition.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Diacetolol absolute oral bioavailability was 0.426 ± 0.068 in healthy subjects after an 800 mg oral dose versus IV, well above 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All evidence molecules, based on their strongest absolute bioavailability records, support F ≥20%; direct human absolute F values range from about 25% to 94%, including a post-prandial measurement of 36.40%. High assay-transfer scores support applicability to the query, and the fed-state condition is directly addressed by the KNI-272 post-prandial record.",
  "evidence_gaps": [
    "Most evidence molecules lack explicit fed-state records; only KNI-272 has a post-prandial measurement. The remaining evidence is from fasting or unspecified conditions, but high assay-transfer scores support extrapolation."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

